{
 public DbSet<ExpenseState> ExpenseStates=>Set<ExpenseState>();public DbSet<Budget> Budgets=>Set<Budget>();public DbSet<BudgetLine> BudgetLines=>Set<BudgetLine>();public DbSet<Vendor> Vendors=>Set<Vendor>();public DbSet<Expense> Expenses=>Set<Expense>();public DbSet<ExpenseApproval> Approvals=>Set<ExpenseApproval>();public DbSet<Payment> Payments=>Set<Payment>();public DbSet<ExpenseAdjustment> Adjustments=>Set<ExpenseAdjustment>();
